code.source:
#include <stdio.h>
#include <string.h>

int main() {
    char first[20] = "Crab";
    char second[] = "Xecxec";
    char copy[20];

    printf("Length of %s: %zu\n", second, strlen(second));

    strcpy(copy, second);
    printf("Copy: %s\n", copy);

    strcat(first, " ");
    strcat(first, second);
    printf("Joined: %s\n", first);

    printf("strcmp(\"apple\", \"apple\") = %d\n", strcmp("apple", "apple"));
    if (strcmp("apple", "mango") < 0) {
        printf("apple comes before mango\n");
    }
    return 0;
}

