#include <stdio.h>
#include <string.h>

int main() {
    char saved[] = "feni@2026";
    char typed[30];

    printf("Password: ");
    fgets(typed, sizeof(typed), stdin);
    typed[strcspn(typed, "\n")] = '\0';

    if (strcmp(typed, saved) == 0) {
        printf("Access granted\n");
    } else {
        printf("Wrong password\n");
    }
    return 0;
}

